// Presentation metadata for the built-in projects. Each variant records the exact
// original it translates; a changed or unknown original is shown untranslated.
// Project records retain their original language. Deployment-specific labels are not bundled.
const DISPLAY_LABELS = {};
// Backend diagnostics are English sentences; known patterns get a Chinese rendering.
const WARNING_PATTERNS = [
  [/^No readable research control event stream is available\.$/, () => 'warn.noResearch'],
  [/^(\d+) referenced fact predecessor\(s\) are missing; placeholder nodes are shown\.$/, (m) => ['{n} 个引用的前置事实缺失，已显示占位节点。', { n: m[1] }]],
  [/^Fact dependencies contain a cycle; the displayed layers are provisional\.$/, () => ['事实依赖中存在环；显示的层级只是暂定。']],
  [/^Research relationships contain a cycle; this layer is not a fact DAG\.$/, () => ['研究关系中存在环；这一层不是事实有向无环图。']],
  [/^(\d+) research relationship\(s\) reference absent nodes\.$/, (m) => ['{n} 条研究关系引用了不存在的节点。', { n: m[1] }]],
  [/^Control events are unavailable or malformed; no mathematical status inferred\.$/, () => ['控制事件不可用或格式有误；不推断任何数学状态。']],
  [/^Control store changed during snapshot; retry on the next refresh\.$/, () => ['读取期间控制库发生变化；下次刷新时重试。']],
  [/^Runtime monitor snapshot is stale; coordinator status is not live\.$/, () => ['运行监测快照已过期；负责人状态不是实时的。']],
  [/^Runtime monitor belongs to a different project; ignored\.$/, () => ['运行监测属于其他项目，已忽略。']],
  [/^Worker (.+): role metadata unavailable\.$/, (m) => ['成员 {name} 的角色信息不可用。', { name: m[1] }]],
  [/^Worker (.+): task summary unavailable\.$/, (m) => ['成员 {name} 的任务摘要不可用。', { name: m[1] }]],
  [/^(.+): source is missing\.$/, (m) => ['{label}：来源缺失。', { label: m[1] }]],
  [/^(.+): source is unreadable or malformed\.$/, (m) => ['{label}：来源不可读或格式有误。', { label: m[1] }]],
];
let currentLang = 'en';
const plural = new Map();
function setCurrentLang(lang) { currentLang = I18N_LANGS.includes(lang) ? lang : 'en'; document.documentElement.lang = I18N_LOCALES[currentLang]; }
function interpolate(template, vars) {
  return template.replace(/\{(\w+)\}/g, (_, name) => vars[name] == null ? '' : typeof vars[name] === 'number' ? fmtNumber(vars[name]) : String(vars[name]));
}
function t(key, vars = {}) {
  let entry = I18N[currentLang][key] ?? I18N.zh[key];
  if (entry == null) return key;
  if (typeof entry === 'object') {
    if (!plural.has(currentLang)) plural.set(currentLang, new Intl.PluralRules(I18N_LOCALES[currentLang]));
    const count = Number(vars.count ?? vars.n ?? 0);
    entry = entry[plural.get(currentLang).select(count)] ?? entry.other;
  }
  return interpolate(entry, vars);
}
const i18nHas = (key) => (I18N[currentLang][key] ?? I18N.zh[key]) != null;
function fmtNumber(value) { return value == null || !Number.isFinite(Number(value)) ? '—' : Number(value).toLocaleString(I18N_LOCALES[currentLang]); }
function fmtDateTime(when) {
  return new Intl.DateTimeFormat(I18N_LOCALES[currentLang], { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).format(when);
}
function fmtTime(when) { return new Intl.DateTimeFormat(I18N_LOCALES[currentLang], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).format(when); }
function fmtRelative(seconds) {
  if (seconds < 60) return t('time.justNow');
  const format = new Intl.RelativeTimeFormat(I18N_LOCALES[currentLang], { numeric: 'auto' });
  if (seconds < 3600) return format.format(-Math.floor(seconds / 60), 'minute');
  if (seconds < 86400) return format.format(-Math.floor(seconds / 3600), 'hour');
  return format.format(-Math.floor(seconds / 86400), 'day');
}
function fmtPercent(value) { return value == null || !Number.isFinite(Number(value)) ? t('quota.unknown') : new Intl.NumberFormat(I18N_LOCALES[currentLang], { maximumFractionDigits: 2 }).format(Number(value)) + '%'; }
function fmtList(items) { return currentLang === 'en' ? items.join(', ') : items.join('、'); }
// Returns { text, translated } for built-in labels; untranslated text remains source content.
function displayLabel(kind, project, key, original) {
  const text = original == null ? '' : String(original);
  const entry = DISPLAY_LABELS[project];
  if (currentLang === 'zh') return { text, translated: true };
  if (!entry) return { text, translated: false };
  let pair = null;
  if (kind === 'node') pair = entry.nodes?.[key];
  else if (kind === 'team' || kind === 'teamDescription') pair = entry.teams?.[key]?.[kind === 'team' ? 'name' : 'description'];
  else if (kind === 'person') pair = (entry.people || []).find(([zh]) => zh === text);
  else pair = entry[kind];
  return pair && pair[0] === text ? { text: pair[1], translated: true } : { text, translated: false };
}
function localizeWarning(message) {
  const value = String(message);
  for (const [pattern, render] of WARNING_PATTERNS) {
    const match = value.match(pattern);
    if (!match) continue;
    const result = render(match);
    if (typeof result === 'string') return t(result);
    return currentLang === 'zh' ? interpolate(result[0], result[1] || {}) : value;
  }
  return value;
}
// Explicitly keyed static markup; never a scan-and-replace over rendered text.
function applyStaticText(root = document) {
  root.querySelectorAll('[data-i18n]').forEach((element) => { element.textContent = t(element.dataset.i18n); });
  root.querySelectorAll('[data-i18n-attr]').forEach((element) => {
    for (const pair of element.dataset.i18nAttr.split(',')) { const [attribute, key] = pair.split(':'); element.setAttribute(attribute.trim(), t(key.trim())); }
  });
}

